<?php
function editor_field(string $key,array $config,string $value): void {
    [$label,$inputType]=$config; $id='field-'.$key;
    echo '<label class="editor-field '.($inputType==='textarea'?'wide':'').'" for="'.e($id).'"><span>'.e($label).'</span>';
    if($inputType==='textarea') echo '<textarea id="'.e($id).'" name="fields['.e($key).']" rows="'.(in_array($key,['body','intro','about_body'])?6:3).'" maxlength="20000">'.e($value).'</textarea>';
    elseif($inputType==='image') {
        echo '<select class="image-select" id="'.e($id).'" name="fields['.e($key).']"><option value="">No image</option>';
        $options=reference_photos();
        foreach(query('SELECT * FROM media ORDER BY id DESC')->fetchAll() as $media) $options[]=$media;
        foreach($options as $option) echo '<option value="'.e($option['path']).'" '.($value===$option['path']?'selected':'').'>'.e($option['alt']).'</option>';
        echo '</select><small>Upload new images in the <a href="/superadmin/media" target="_blank" rel="noopener">media library</a>, then reload this editor.</small>';
        if(image_path($value)) echo '<img class="field-image-preview" src="'.e($value).'" alt="Selected image preview">';
    }
    else echo '<input id="'.e($id).'" name="fields['.e($key).']" type="'.e($inputType).'" value="'.e($value).'" maxlength="'.($inputType==='text'?6000:1000).'">';
    echo '</label>';
}
?>
